CREATE OR REPLACE FUNCTION public.fb_claim_group_join(_job uuid,_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.fb_group_join_jobs; BEGIN SELECT * INTO j FROM public.fb_group_join_jobs WHERE id=_job AND dispatch_token=_token; IF j.id IS NULL THEN RETURN false; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(j.workspace_owner_id::text,1)); IF EXISTS(SELECT 1 FROM public.fb_group_join_jobs WHERE workspace_owner_id=j.workspace_owner_id AND status='processing' AND claim_expires_at>now()) THEN RETURN false; END IF; UPDATE public.fb_group_join_jobs SET status='processing',attempts=attempts+1,claim_expires_at=now()+interval '10 minutes',updated_at=now() WHERE id=_job AND dispatch_token=_token AND status IN ('queued','requested') AND available_at<=now(); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.fb_claim_group_join(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fb_claim_group_join(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.fb_claim_cloud_group_post(_job uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.campaign_activity_queue; BEGIN SELECT * INTO q FROM public.campaign_activity_queue WHERE id=_job FOR UPDATE; IF q.id IS NULL OR q.status<>'pending' OR q.runner<>'cloud' THEN RETURN false; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(q.workspace_owner_id::text,0)); IF NOT public.fb_prepare_cloud_group_post(_job) THEN RETURN false; END IF; UPDATE public.campaign_activity_queue SET status='processing',processed_at=now(),claim_expires_at=now()+interval '10 minutes',cloud_attempts=coalesce(cloud_attempts,0)+1,last_error=NULL WHERE id=_job AND status='pending'; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.fb_claim_cloud_group_post(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fb_claim_cloud_group_post(uuid) TO service_role;